/** Independent read/preview/confirm UI. Native evidence is never constructed from a menu click. */
public final class GovernanceMenu implements Listener {
    private final WorldRuntime runtime;
    public GovernanceMenu(WorldRuntime runtime){this.runtime=Objects.requireNonNull(runtime);}
    private enum Page { HOME,WORKS,WORKS_PREVIEW,WORKS_STATUS,WORKS_HISTORY,CIVIC,CIVIC_PREVIEW,CIVIC_STATUS,CIVIC_COMPLETE,CIVIC_HISTORY,LIFE }
    private static final class Holder implements InventoryHolder {
        final UUID viewer;final CoreCity city;final Page page;final int offset,limit;final Map<Integer,Consumer<Player>> actions=new HashMap<>();Inventory inventory;
        Holder(UUID viewer,CoreCity city,Page page,int offset,int limit){this.viewer=viewer;this.city=city;this.page=page;this.offset=offset;this.limit=limit;}
        public Inventory getInventory(){return inventory;}
    }
    private record State(CityView city,Profile profile,LifeView life,List<Project> projects,List<dev.starworld.works.PublicWorksState.History> worksHistory,List<Request> requests,List<dev.starworld.civic.CivicNeedsState.History> civicHistory){State{projects=List.copyOf(projects);worksHistory=List.copyOf(worksHistory);requests=List.copyOf(requests);civicHistory=List.copyOf(civicHistory);}}
    public void open(Player player){openPage(player,Page.HOME,0);}
    public void openWorks(Player player,int offset){openPage(player,Page.WORKS_STATUS,offset);}
    public void openCivic(Player player,int offset){openPage(player,Page.CIVIC_STATUS,offset);}
    private CoreCity current(Player player){if(!player.hasPermission("starworld.use"))throw new IllegalArgumentException("需要 starworld.use 权限");if(runtime.expansion().isEmpty())throw new IllegalArgumentException("扩展模块未启用");return runtime.playerCity(player).orElseThrow(()->new IllegalArgumentException("请先加入 StarCore 城市"));}
    private static Inventory top(Player player){InventoryView view=player.getOpenInventory();return view==null?null:view.getTopInventory();}
    private boolean same(Player player,CoreCity city){return player.isOnline()&&player.hasPermission("starworld.use")&&runtime.playerCity(player).filter(c->c.cityId().equals(city.cityId())&&c.nationId().equals(city.nationId())).isPresent();}
    private boolean canOpen(Player player,CoreCity city,Inventory source){return same(player,city)&&top(player)==source;}
    private boolean showing(Player p,Holder h){return same(p,h.city)&&top(p)!=null&&top(p).getHolder()==h;}
    private int limit(Page page){var x=runtime.expansion().orElseThrow();return Math.min(8,isCivic(page)?x.civic().definitions().maximumPage():x.works().configuration().data().maxPage());}
    private int maximumOffset(Page page){return isCivic(page)?runtime.expansion().orElseThrow().civic().definitions().maximumOffset():1_000_000;}
    private static boolean isCivic(Page page){return page==Page.CIVIC||page==Page.CIVIC_PREVIEW||page==Page.CIVIC_STATUS||page==Page.CIVIC_COMPLETE||page==Page.CIVIC_HISTORY;}
    private void openPage(Player player,Page page,int offset){
        CoreCity city=current(player);Inventory source=top(player);int limit=limit(page);if(offset<0||offset>maximumOffset(page))throw new IllegalArgumentException("治理页码超限");var x=runtime.expansion().orElseThrow();long period=runtime.currentPeriod();
        runtime.reply(player,runtime.city(city.cityId()).thenCompose(optional->runtime.async(()->{
            CityView view=optional.orElseThrow(()->new IllegalArgumentException("城市尚未登记扩展状态，请先登记设施"));int worksLimit=isCivic(page)?Math.min(8,x.works().configuration().data().maxPage()):limit,civicLimit=isCivic(page)?limit:Math.min(8,x.civic().definitions().maximumPage());
            return new State(view,x.evolution().profile(city.cityId()),x.life().view(city.cityId(),period),x.works().projects(city.cityId(),worksLimit,isCivic(page)?0:offset),x.works().history(city.cityId(),worksLimit,isCivic(page)?0:offset),x.civic().requests(city.cityId(),civicLimit,isCivic(page)?offset:0),x.civic().history(city.cityId(),civicLimit,isCivic(page)?offset:0));
        })),state->{if(!canOpen(player,city,source)||!state.city().nationId().equals(city.nationId()))return;Holder h=holder(player,city,page,offset,limit,title(page));header(h,state);
            switch(page){
                case HOME->{button(h,10,Material.BRICKS,"公共工程选项",List.of("有限城市/国家永久工程槽","预览起建、逐期施工和运行维护成本"),p->openPage(p,Page.WORKS,0));button(h,12,Material.WRITABLE_BOOK,"城市需求选项",List.of("先发起，再提交真实材料与请求后生活凭据","发起不扣料；完成时事务扣料与认领凭据"),p->openPage(p,Page.CIVIC,0));button(h,14,Material.JUKEBOX,"已发生生活贡献",List.of("真实生活文化、家具登记和演奏会话","此页不制造需求完成凭据"),p->openPage(p,Page.LIFE,0));button(h,16,Material.WATER_BUCKET,"灾害治理",List.of("打开已安装的灾害治理界面"),p->p.performCommand("sw disaster-menu"));h.inventory.setItem(22,item(Material.PAPER,"城市实物仓储",wrap(state.city().stock().toString())));}
                case WORKS->{int slot=9;for(ProjectDefinition definition:x.works().configuration().projects().values().stream().sorted(Comparator.comparing(ProjectDefinition::id)).toList()){List<String> lore=new ArrayList<>(worksLore(definition,state));lore.add("点击预览当前门槛和库存缺口");button(h,slot++,Material.BRICKS,definition.name(),lore,p->openWorksPreview(p,definition.id()));}}
                case WORKS_STATUS->{int slot=9;for(Project project:state.projects()){String reason=state.worksHistory().stream().filter(row->row.requestId().equals(project.requestId())&&row.kind().contains("paused")).findFirst().map(row->"最近暂停记录 ["+row.period()+"] "+row.detail()).orElse("当前页没有暂停凭据；下一结算继续复核");h.inventory.setItem(slot++,item(Material.SMITHING_TABLE,project.definition().name(),List.of("请求："+project.requestId(),"原国家："+project.nationId(),"施工："+project.progress()+" / "+project.definition().buildPeriods(),"最近施工尝试："+project.lastConstructionAttemptPeriod(),"完成周期："+project.completedPeriod(),"最近运行周期："+project.lastOperationPeriod(),"该期维护已付："+project.lastOperationPaid(),reason,"起建已付："+project.definition().upfrontCosts(),"每步施工："+project.definition().constructionCosts(),"运行维护："+project.definition().upkeepCosts())));}if(slot==9)empty(h,"本页没有公共工程");button(h,42,Material.BRICKS,"工程选项",List.of(),p->openPage(p,Page.WORKS,0));button(h,44,Material.BOOK,"工程历史与暂停原因",List.of(),p->openPage(p,Page.WORKS_HISTORY,0));pagination(h,state.projects().size()==limit);}
                case WORKS_HISTORY->{int slot=9;for(var history:state.worksHistory()){List<String> lore=new ArrayList<>(List.of("请求："+history.requestId(),"周期："+history.period()));lore.addAll(wrap(history.detail()));h.inventory.setItem(slot++,item(Material.BOOK,history.kind(),lore));}if(slot==9)empty(h,"本页没有工程历史");pagination(h,state.worksHistory().size()==limit);}
                case CIVIC->{int slot=9;for(Need need:x.civic().definitions().needs().values().stream().sorted(Comparator.comparing(Need::id)).toList()){List<String> lore=needLore(need,state);lore.add("点击预览；发起时不扣材料");button(h,slot++,Material.WRITABLE_BOOK,need.name(),lore,p->openNeedPreview(p,need.id()));}}
                case CIVIC_STATUS->{int slot=9;for(Request request:state.requests()){List<String> lore=needLore(request.definition(),state);lore.addAll(List.of("请求："+request.id(),"原国家："+request.nationId(),"状态："+(request.expiredAt(runtime.currentPeriod())?"已过期":request.status()),"请求 / 到期："+request.requestedPeriod()+" / "+request.expiryPeriod(),"点击预览并明确提交完成"));button(h,slot++,Material.PAPER,request.definition().name(),lore,p->openNeedCompletion(p,request.id()));}if(slot==9)empty(h,"本页没有城市需求");button(h,42,Material.WRITABLE_BOOK,"需求选项",List.of(),p->openPage(p,Page.CIVIC,0));button(h,44,Material.BOOK,"需求完成历史",List.of(),p->openPage(p,Page.CIVIC_HISTORY,0));pagination(h,state.requests().size()==limit);}
                case CIVIC_HISTORY->{int slot=9;for(var history:state.civicHistory()){List<String> lore=new ArrayList<>(List.of("请求："+history.requestId(),"周期："+history.period()));lore.addAll(wrap(history.detail()));h.inventory.setItem(slot++,item(Material.BOOK,history.kind(),lore));}if(slot==9)empty(h,"本页没有需求历史");pagination(h,state.civicHistory().size()==limit);}
                case LIFE->{h.inventory.setItem(10,item(Material.JUKEBOX,"已提交生活文化",List.of("累计："+state.life().culture(),"当前有限产能倍率："+state.life().productionMultiplier(),"城市最近家具维护周期："+state.life().decorationPeriod(),"家具登记数量："+state.life().decorations().size(),"进行中演奏会话："+state.life().concerts().size(),"登记不是已提交维护凭据","需求仍核验请求后的未认领凭据")));int slot=18;for(var concert:state.life().concerts().stream().limit(8).toList())h.inventory.setItem(slot++,item(Material.NOTE_BLOCK,"演奏："+concert.state(),List.of("会话："+concert.id(),"开始周期："+concert.startPeriod(),"真实音符："+concert.notes()+"；听众："+concert.audience(),"该会话仍在进行中；完成后仍须由需求事务核验")));}
                default->throw new IllegalArgumentException("Preview pages require an explicit selection");
            }
            footer(h);player.openInventory(h.inventory);
        });
    }
    public void openWorksPreview(Player player,String definitionId){
        CoreCity city=current(player);Inventory source=top(player);var x=runtime.expansion().orElseThrow();ProjectDefinition definition=x.works().configuration().projects().get(definitionId);if(definition==null)throw new IllegalArgumentException("公共工程配置已移除");
        runtime.reply(player,runtime.city(city.cityId()),optional->{if(!canOpen(player,city,source))return;CityView view=optional.orElseThrow(()->new IllegalArgumentException("城市尚未登记"));if(!view.nationId().equals(city.nationId()))return;Set<UUID> verified=runtime.verifiedBuildings(view);long period=runtime.currentPeriod();
            runtime.reply(player,runtime.async(()->new WorksPreview(view,x.evolution().profile(city.cityId()),x.works().inspect(city,view,period,verified))),preview->{if(!canOpen(player,city,source))return;UUID requestId=UUID.randomUUID();Holder h=holder(player,city,Page.WORKS_PREVIEW,0,0,"公共工程 · 明确确认");List<String> lore=new ArrayList<>(List.of("工程："+definition.id(),"施工："+definition.buildPeriods()+" 个实际结算","设施："+definition.facilities(),"适用地形："+definition.terrains(),"规划要求："+definition.plans()+"；当前："+preview.profile().plan(),"文明要求："+definition.civilizations()+"；当前："+view.civilization(),"知识："+preview.profile().knowledge()+" / "+definition.knowledge(),"文化："+preview.profile().culture()+" / "+definition.culture(),"每步施工："+definition.constructionCosts(),"运行维护："+definition.upkeepCosts(),"倍率取舍："+definition.multipliers()));h.inventory.setItem(13,item(Material.BRICKS,definition.name(),lore));h.inventory.setItem(21,item(Material.CHEST,"起建真实物资与缺口",costs(view,definition.upfrontCosts())));Feasibility feasibility=preview.feasibility().stream().filter(f->f.definitionId().equals(definitionId)).findFirst().orElseThrow();List<String> confirmation=new ArrayList<>(List.of("请求："+requestId,"起建成功时一次扣料；次期开始施工","各步与运行仍需付费并持续满足门槛","重复点击本页保留相同UUID"));boolean allowed=runtime.manage(player,city.cityId())&&feasibility.eligible();confirmation.add(allowed?"点击确认起建":!runtime.manage(player,city.cityId())?"需要城市管理权限":feasibility.reason());if(allowed)button(h,31,Material.LIME_DYE,"确认起建并支付",confirmation,p->x.startPublicWorks(p,city,definitionId,requestId,project->{if(showing(p,h))openWorks(p,0);}));else h.inventory.setItem(31,item(Material.BARRIER,"暂时无法起建",confirmation));footer(h);player.openInventory(h.inventory);});
        });
    }
    private record WorksPreview(CityView city,Profile profile,List<Feasibility> feasibility){WorksPreview{feasibility=List.copyOf(feasibility);}}
    public void openNeedPreview(Player player,String needId){
        CoreCity city=current(player);Inventory source=top(player);var x=runtime.expansion().orElseThrow();Need need=x.civic().definitions().needs().get(needId);if(need==null)throw new IllegalArgumentException("城市需求配置已移除");
        runtime.reply(player,runtime.city(city.cityId()),optional->{if(!canOpen(player,city,source))return;CityView view=optional.orElseThrow(()->new IllegalArgumentException("城市尚未登记"));if(!view.nationId().equals(city.nationId()))return;UUID requestId=UUID.randomUUID();Holder h=holder(player,city,Page.CIVIC_PREVIEW,0,0,"城市需求 · 发起确认");h.inventory.setItem(13,item(Material.WRITABLE_BOOK,need.name(),needTerms(need)));h.inventory.setItem(21,item(Material.CHEST,"完成时才支付；可在请求后备料",costs(view,need.costs())));List<String> lore=new ArrayList<>(List.of("请求："+requestId,"现在不扣材料，不奖励属性","请求后的实际贡献才可能被认领","重复点击此页使用相同UUID","发起后在需求状态中预览并确认完成"));Optional<String> unavailable=x.civicUnavailable(needId);unavailable.ifPresent(reason->lore.add("\u5f53\u524d\u6682\u4e0d\u53ef\u7528："+reason));if(runtime.manage(player,city.cityId())&&unavailable.isEmpty())button(h,31,Material.LIME_DYE,"确认发起需求（不扣料）",List.copyOf(lore),p->x.requestCivicNeed(p,city,needId,requestId,request->{if(showing(p,h))openCivic(p,0);}));else h.inventory.setItem(31,item(Material.BARRIER,unavailable.orElse("需要城市管理权限"),lore));footer(h);player.openInventory(h.inventory);});
    }
    public void openNeedCompletion(Player player,UUID requestId){
        CoreCity city=current(player);Inventory source=top(player);var x=runtime.expansion().orElseThrow();
        runtime.reply(player,runtime.city(city.cityId()).thenCompose(optional->runtime.async(()->new NeedCompletion(optional.orElseThrow(()->new IllegalArgumentException("城市尚未登记")),x.civic().request(requestId).orElseThrow(()->new IllegalArgumentException("城市需求不存在")),x.life().view(city.cityId(),runtime.currentPeriod())))),read->{if(!canOpen(player,city,source)||!read.city().nationId().equals(city.nationId()))return;Request request=read.request();Holder h=holder(player,city,Page.CIVIC_COMPLETE,0,0,"城市需求 · 完成确认");List<String> terms=new ArrayList<>(needTerms(request.definition()));terms.add("请求："+request.id());terms.add("请求 / 期限："+request.requestedPeriod()+" / "+request.expiryPeriod());terms.add("当前保存状态："+request.status());h.inventory.setItem(13,item(Material.PAPER,request.definition().name(),terms));h.inventory.setItem(21,item(Material.CHEST,"实际完成材料",costs(read.city(),request.definition().costs())));h.inventory.setItem(23,item(Material.JUKEBOX,"已发生贡献参考（不代替凭据）",List.of("累计生活文化："+read.life().culture(),"登记家具："+read.life().decorations().size()+"（不是维护回执）","进行中演奏会话："+read.life().concerts().size(),"只认请求后、同国、已提交且未认领的贡献","真实凭据和实际奖励由完成事务返回")));String blocked=completionBlocked(player,city,read);List<String> confirmation=List.of("请求："+request.id(),"同一请求UUID反复提交不会重复扣料/奖励","后台选择真实生活凭据；界面不伪造凭据","提交成功后显示实际材料、动作UUID与奖励");if(blocked==null)button(h,31,Material.LIME_DYE,request.status()==Status.COMPLETED?"读取原完成回执":"确认提交材料和真实贡献",confirmation,p->x.completeCivicNeed(p,city,request.id(),receipt->{if(showing(p,h)){p.sendMessage("§e真实回执："+receipt);openCivic(p,0);}}));else{List<String> reason=new ArrayList<>(confirmation);reason.add(blocked);h.inventory.setItem(31,item(Material.BARRIER,"暂时不能完成",reason));}footer(h);player.openInventory(h.inventory);});
    }
    private record NeedCompletion(CityView city,Request request,LifeView life){}
    private String completionBlocked(Player p,CoreCity city,NeedCompletion read){Request r=read.request();if(!runtime.manage(p,city.cityId()))return "需要城市管理权限";if(!r.cityId().equals(city.cityId())||!r.nationId().equals(city.nationId()))return "需求属于另一城市或原国家";if(r.status()==Status.COMPLETED)return null;long period=runtime.currentPeriod();if(r.status()!=Status.OPEN||r.expiredAt(period))return "需求已过期或失效";if(period<=r.requestedPeriod())return "最早下一周期提交真实请求后贡献";if(!missing(read.city(),r.definition().costs()).isEmpty())return "城市真实材料不足";return null;}
    private Holder holder(Player p,CoreCity city,Page page,int offset,int limit,String title){Holder h=new Holder(p.getUniqueId(),city,page,offset,limit);h.inventory=Bukkit.createInventory(h,54,Component.text("StarWorld · "+title));return h;}
    private void header(Holder h,State state){h.inventory.setItem(4,item(Material.BEACON,state.city().name(),List.of("国家："+h.city.nationName(),"规划 / 文明："+state.profile().plan()+" / "+state.city().civilization(),"知识 / 文化："+state.profile().knowledge()+" / "+state.profile().culture(),"稳定 / 繁荣："+state.profile().stability()+" / "+state.profile().prosperity(),"快照周期："+state.city().lastPeriod())));}
    private void footer(Holder h){button(h,45,Material.ARROW,"治理总览",List.of(),this::open);button(h,46,Material.SMITHING_TABLE,"工程进度与状态",List.of(),p->openWorks(p,0));button(h,47,Material.PAPER,"城市需求状态",List.of(),p->openCivic(p,0));button(h,48,Material.JUKEBOX,"真实生活贡献",List.of(),p->openPage(p,Page.LIFE,0));button(h,49,Material.WATER_BUCKET,"灾害治理入口",List.of(),p->p.performCommand("sw disaster-menu"));if(h.page!=Page.WORKS_PREVIEW&&h.page!=Page.CIVIC_PREVIEW&&h.page!=Page.CIVIC_COMPLETE)button(h,53,Material.SUNFLOWER,"刷新当前页面",List.of(),p->openPage(p,h.page,h.offset));else h.inventory.setItem(53,item(Material.PAPER,"重试保留本页UUID",List.of("确认失败时可在同页重试","离开后可用聊天命令与已显示UUID对账")));}
    private void pagination(Holder h,boolean next){if(h.offset>0)button(h,51,Material.ARROW,"上一页",List.of(),p->openPage(p,h.page,Math.max(0,h.offset-h.limit)));if(next&&h.offset<=maximumOffset(h.page)-h.limit)button(h,52,Material.ARROW,"下一页",List.of(),p->openPage(p,h.page,h.offset+h.limit));}
    private List<String> worksLore(ProjectDefinition d,State state){return List.of("ID："+d.id(),"起建成本："+d.upfrontCosts(),"当前起建缺口："+missing(state.city(),d.upfrontCosts()),"施工："+d.buildPeriods()+" 步；每步="+d.constructionCosts(),"运行维护："+d.upkeepCosts(),"设施 / 地形："+d.facilities()+" / "+d.terrains(),"规划 / 文明："+d.plans()+" / "+d.civilizations(),"知识 / 文化门槛："+d.knowledge()+" / "+d.culture(),"产能取舍："+d.multipliers());}
    private List<String> needLore(Need need,State state){List<String> lore=new ArrayList<>(needTerms(need));lore.add("当前材料缺口："+missing(state.city(),need.costs()));lore.add("真实累计生活文化："+state.life().culture()+"（不等于可用凭据数）");runtime.expansion().orElseThrow().civicUnavailable(need.id()).ifPresent(reason->lore.add("当前暂不可用："+reason));return lore;}
    private static List<String> needTerms(Need need){return List.of("ID："+need.id(),"完成材料："+need.costs(),"请求后真实贡献："+need.actionKind()+" ×"+need.actionCount(),need.distinctSources()?"必须来自不同家具的已提交维护；缺少家具API时暂停":"只认已提交宴会或已完成受控演奏","期限 / 冷却窗口："+need.lifetimePeriods()+" / "+need.cooldownPeriods(),"本地稳定 / 繁荣最多："+need.stabilityReward()+" / "+need.prosperityReward(),"实际奖励封顶100；不会发资源或经验");}
    private static Map<String,Long> missing(CityView city,Map<String,Long> costs){Map<String,Long> result=new TreeMap<>();costs.forEach((id,n)->{long lack=n-city.stock().getOrDefault(id,0L);if(lack>0)result.put(id,lack);});return Map.copyOf(result);}
    private static List<String> costs(CityView city,Map<String,Long> costs){List<String> lines=new ArrayList<>();costs.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->lines.add(e.getKey()+" ×"+e.getValue()+"；库存="+city.stock().getOrDefault(e.getKey(),0L)+"；缺口="+Math.max(0,e.getValue()-city.stock().getOrDefault(e.getKey(),0L))));return lines;}
    private static String title(Page page){return switch(page){case HOME->"城市治理总览";case WORKS->"公共工程选项";case WORKS_STATUS->"公共工程状态";case WORKS_HISTORY->"公共工程历史";case CIVIC->"城市需求选项";case CIVIC_STATUS->"城市需求状态";case CIVIC_HISTORY->"城市需求历史";case LIFE->"已发生生活贡献";default->"治理预览";};}
    private static void empty(Holder h,String label){h.inventory.setItem(22,item(Material.PAPER,label,List.of("当前页面为只读，不会推进结算或产生凭据")));}
    private static void button(Holder h,int slot,Material icon,String name,List<String> lore,Consumer<Player> action){h.inventory.setItem(slot,item(icon,name,lore));h.actions.put(slot,action);}
    private static ItemStack item(Material icon,String name,List<String> lore){ItemStack stack=new ItemStack(icon);ItemMeta meta=stack.getItemMeta();meta.displayName(Component.text(name));meta.lore(lore.stream().map(Component::text).toList());stack.setItemMeta(meta);return stack;}
    private static List<String> wrap(String value){if(value==null||value.isBlank())return List.of("无记录");List<String> lines=new ArrayList<>();for(int i=0;i<value.length()&&lines.size()<12;i+=40)lines.add(value.substring(i,Math.min(i+40,value.length())));return lines;}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false) public void click(InventoryClickEvent event){
        if(!(event.getView().getTopInventory().getHolder() instanceof Holder holder))return;event.setCancelled(true);if(event.getClick()!=ClickType.LEFT&&event.getClick()!=ClickType.RIGHT)return;if(!(event.getWhoClicked() instanceof Player player)||!player.getUniqueId().equals(holder.viewer)||event.getRawSlot()<0||event.getRawSlot()>=54)return;Consumer<Player> action=holder.actions.get(event.getRawSlot());if(action==null)return;
        Bukkit.getScheduler().runTask(JavaPlugin.getProvidingPlugin(GovernanceMenu.class),()->{if(!player.isOnline()||top(player)==null||top(player).getHolder()!=holder)return;if(!same(player,holder.city)){player.closeInventory();return;}try{action.accept(player);}catch(Exception error){player.sendMessage("§c"+error.getMessage());}});
    }
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false) public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof Holder)event.setCancelled(true);}
}
